// Static part: before the player exists

void AGBTestArena::BuildStatic()
{
	UWorld* World = GetWorld();
	if (bStaticBuilt || !World)
	{
		return;
	}
	bStaticBuilt = true;
	using namespace ArenaLayout;

	// ---- Lighting: movable sun, real-time sky light, atmosphere, height fog ----
	Sun = World->SpawnActor<ADirectionalLight>(ADirectionalLight::StaticClass(), FVector(0.f, 0.f, 1000.f), SunRotation, AlwaysSpawnParams());
	if (Sun)
	{
		if (UDirectionalLightComponent* SunComponent = Sun->GetComponent())
		{
			SunComponent->SetMobility(EComponentMobility::Movable);
			SunComponent->SetAtmosphereSunLight(true);
			SunComponent->SetCastShadows(true);
		}
	}
	SkyLight = World->SpawnActor<ASkyLight>(ASkyLight::StaticClass(), FVector(0.f, 0.f, 500.f), FRotator::ZeroRotator, AlwaysSpawnParams());
	if (SkyLight)
	{
		if (USkyLightComponent* SkyComponent = SkyLight->GetLightComponent())
		{
			SkyComponent->SetMobility(EComponentMobility::Movable);
			SkyComponent->SetRealTimeCapture(true);
		}
	}
	World->SpawnActor<ASkyAtmosphere>(ASkyAtmosphere::StaticClass(), FVector::ZeroVector, FRotator::ZeroRotator, AlwaysSpawnParams());
	Fog = World->SpawnActor<AExponentialHeightFog>(AExponentialHeightFog::StaticClass(), FVector::ZeroVector, FRotator::ZeroRotator, AlwaysSpawnParams());
	ApplyEraLighting(EGBEra::Past);

	// ---- Floor and perimeter walls ----
	const float Outer = HalfSize + WallThickness * 0.5f;
	const float FullSpan = HalfSize * 2.f + WallThickness * 2.f;
	SpawnBlock(FVector(0.f, 0.f, -FloorThickness * 0.5f), FVector(FullSpan, FullSpan, FloorThickness), Floor);
	SpawnBlock(FVector(0.f, Outer, WallHeight * 0.5f), FVector(FullSpan, WallThickness, WallHeight), Wall);
	SpawnBlock(FVector(0.f, -Outer, WallHeight * 0.5f), FVector(FullSpan, WallThickness, WallHeight), Wall);
	SpawnBlock(FVector(Outer, 0.f, WallHeight * 0.5f), FVector(WallThickness, FullSpan, WallHeight), Wall);
	SpawnBlock(FVector(-Outer, 0.f, WallHeight * 0.5f), FVector(WallThickness, FullSpan, WallHeight), Wall);

	// ---- Movement course: double-jump steps, then a dash gap to the landing block ----
	for (const FVector2D& Step : Steps)
	{
		SpawnBlock(FVector(Step.X, CourseY, Step.Y * 0.5f), FVector(StepSize, StepSize, Step.Y), Course);
	}
	const FVector2D& LastStep = Steps[UE_ARRAY_COUNT(Steps) - 1];
	const float LandingX = LastStep.X + StepSize + DashGap;
	SpawnBlock(FVector(LandingX, CourseY, LastStep.Y * 0.5f), FVector(StepSize, StepSize, LastStep.Y), Course);

	// ---- Raised platform (the ramp is gameplay: it depends on era and a flag) ----
	SpawnBlock(FVector(PlatformCenter.X, PlatformCenter.Y, PlatformTop * 0.5f), FVector(PlatformSize.X, PlatformSize.Y, PlatformTop), Platform);

	// ---- Era-gated room walls (the doorway blocker is gameplay) ----
	const float RoomSouthY = -HalfSize;
	const float RoomEastX = HalfSize;
	const float RoomDepth = RoomNorthY - RoomSouthY + WallThickness * 0.5f;
	SpawnBlock(FVector(RoomWestX, RoomSouthY + RoomDepth * 0.5f, WallHeight * 0.5f), FVector(WallThickness, RoomDepth, WallHeight), Wall);
	const float DoorWestX = DoorCenterX - DoorWidth * 0.5f;
