// Placeholder looks built from engine assets only, so the game needs no art to run (GDD 0.1 "Placeholders first").
#pragma once

#include "CoreMinimal.h"

class UStaticMesh;
class UStaticMeshComponent;
class UMaterialInstanceDynamic;

enum class EGBShape : uint8
{
	Cube,
	Sphere,
	Cylinder,
	Cone,
	Plane
};

/**
 * Engine basic shapes (/Engine/BasicShapes/*, 100 cm across) tinted with a dynamic material.
 * Use it for everything 3D that has no art yet: guns, cyberpunk props, walls, floors, 3D enemies.
 * Pixel-art things use UGBPixelSpriteLibrary instead (art rule, GDD 3).
 * Assets are loaded at runtime with LoadObject; DefaultGame.ini keeps them in the cook.
 */
namespace GBPlaceholder
{
	GLYPHBOUND_API UStaticMesh* GetShapeMesh(EGBShape Shape);

	/**
	 * Gives a mesh component a shape, scales it to SizeCm (full extent on each axis, in the component's local
	 * space) and tints it. bGlow uses the engine's unlit additive material (spell and neon looks) instead of
	 * the lit one. Returns the dynamic material so the caller can change the color later ("Color" parameter).
	 * Does not touch the component's collision settings.
	 */
	GLYPHBOUND_API UMaterialInstanceDynamic* SetupShape(UStaticMeshComponent* Component, EGBShape Shape, const FVector& SizeCm, const FLinearColor& Color, bool bGlow = false);

	/**
	 * A 3D shape covered with a pixel-art texture: the look of every medieval / magic STRUCTURE (GDD 3: "pixel-art
	 * environments are 3D geometry with low-resolution pixel textures"): castle walls and floors, the ice wall...
	 * Sprites that face the camera are only for characters, items and effects, never for structures.
	 * TextureId is a sprite id from Sprites.json used as a repeating tile (nearest filtering). The texture is
	 * projected in world space, so it keeps the same pixel size on every face whatever the shape's scale:
	 * one tile covers TileSizeCm x TileSizeCm. Lit material (modern lighting on retro textures); bGlow makes it
	 * also emit its own color (magic). Material: /Game/Glyphbound/Materials/M_PixelSurface, generated by
	 * Tools/Jam/make_materials.py. If the material is missing it falls back to SetupShape with Tint and logs once.
	 * Returns the dynamic material (parameters "Texture", "Tint", "TileSize", "Glow").
	 */
	GLYPHBOUND_API UMaterialInstanceDynamic* SetupTexturedShape(UStaticMeshComponent* Component, EGBShape Shape, const FVector& SizeCm, FName TextureId, float TileSizeCm = 100.f, const FLinearColor& Tint = FLinearColor::White, bool bGlow = false);

	/** Changes the tint of a component set up with SetupShape. */
	GLYPHBOUND_API void SetShapeColor(UStaticMeshComponent* Component, const FLinearColor& Color);

	/** Display color of an element, for placeholders and HUD (fire = orange, lightning = yellow, ice = cyan...). */
	GLYPHBOUND_API FLinearColor ElementColor(uint8 ElementAsByte);
}

// Put it on any actor that exists in only one era, or that depends on a progress flag.
#pragma once

#include "CoreMinimal.h"
#include "Components/ActorComponent.h"
#include "Core/GBTypes.h"
#include "GBEraComponent.generated.h"

/**
 * Decides whether its owner is "present": visible, colliding and ticking. Present when ALL of these hold:
 *  - the current era matches Presence;
 *  - RequiredFlag is empty or set   (cross-era unlock: "open in the future because of what was done in the past");
 *  - RemovedByFlag is empty or not set (a barrier that disappears once something is done).
 * Era-gated zones (GDD 4) are built with this: a wall that is PastOnly, a bridge that is FutureOnly and
 * requires the flag set by a past encounter, etc. Flags live in UGBProgressSubsystem.
 */
UCLASS(ClassGroup = (Glyphbound), meta = (BlueprintSpawnableComponent))
class GLYPHBOUND_API UGBEraComponent : public UActorComponent
{
	GENERATED_BODY()

public:
	UGBEraComponent();

	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Glyphbound|Era")
	EGBEraPresence Presence = EGBEraPresence::Both;

	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Glyphbound|Era")
	FName RequiredFlag = NAME_None;

	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Glyphbound|Era")
	FName RemovedByFlag = NAME_None;

	/** For actors spawned at runtime: set the fields, then call this. */
	void Configure(EGBEraPresence InPresence, FName InRequiredFlag = NAME_None, FName InRemovedByFlag = NAME_None);

	bool IsPresent() const { return bPresent; }

	/** Re-evaluates and applies (called on era change and flag change). */
	void Refresh();

	/** Pure rule, also used by the tests. */
	static bool ComputePresent(EGBEraPresence Presence, EGBEra CurrentEra, bool bRequiredFlagOk, bool bRemovedFlagSet);

	/** Fired when presence flips, after it is applied. Enemies use it to pause their AI. */
	FSimpleMulticastDelegate OnPresenceChanged;

protected:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type EndPlayReason) override;

	void ApplyPresence(bool bNewPresent);
	void HandleEraChanged(EGBEra NewEra);
	void HandleFlagChanged(FName Flag);

	FDelegateHandle EraChangedHandle;
	FDelegateHandle FlagChangedHandle;
	bool bSavedHidden = false;

	bool bPresent = true;
	/** The owner's own collision / tick settings, remembered so presence can be restored exactly. */
	bool bSavedCollision = true;
	bool bSavedTick = true;
	bool bHasSaved = false;
	/** Owner components whose tick was enabled when presence was lost (attributes, status effects...): re-enabled exactly on return, so nothing simulates in the other era. */
	TArray<TWeakObjectPtr<UActorComponent>> SavedTickComponents;
};

