	void InputPause();
	void InputMenuNavigate(const FInputActionValue& Value);
	void InputMenuConfirm();
	void InputMenuBack();
	void InputMenuTab(const FInputActionValue& Value);

	UPROPERTY() TObjectPtr<UGBInputSet> InputSet;
	EGBMenu OpenMenu = EGBMenu::None;
};

