bool UNavigationSystemV1::DoesAnyNavDataRequireGeometryStorage() const
{
	UWorld* World = GetWorld();
	check(World);

	if (!World->IsGameWorld())
	{
		return true;
	}

	for (ANavigationData* NavData : NavDataSet)
	{
		if (NavData && (NavData->GetRuntimeGenerationMode() == ERuntimeGenerationType::Dynamic || NavData->RequiresInitialRebuild()))
		{
			return true;
		}
	}

	return false;
}

