void ARecastNavMesh::ConditionalConstructGenerator()
{	
	if (NavDataGenerator.IsValid())
	{
		NavDataGenerator->CancelBuild();
		NavDataGenerator.Reset();
	}

	UWorld* World = GetWorld();
	check(World);

	// Per-world progressive-build override from the navigation system config, applied before the generator inits
	// (its Init reads bEnableProgressiveBuild). Lets a map enable background coverage without project-global config.
	if (const AWorldSettings* WorldSettings = World->GetWorldSettings())
	{
		if (const UNavigationSystemConfig* NavConfig = WorldSettings->GetNavigationSystemConfig())
		{
			if (NavConfig->ProgressiveBuildOverride != ENavConfigOverride::UseProjectSetting)
			{
				const bool bOverridden = (NavConfig->ProgressiveBuildOverride == ENavConfigOverride::ForceEnabled);

				UE_CLOGF(bEnableProgressiveBuild != bOverridden, LogNavigation, Log,
					"%ls: bEnableProgressiveBuild overridden to %ls by per-world NavigationSystemConfig.",
					*GetName(), bOverridden ? TEXT("true") : TEXT("false"));

				bEnableProgressiveBuild = bOverridden;
			}
		}
	}

	const bool bRequiresGenerator = SupportsRuntimeGeneration() || !World->IsGameWorld();
	if (bRequiresGenerator)
	{
		FRecastNavMeshGenerator* Generator = CreateGeneratorInstance();
		if (Generator)
		{
			NavDataGenerator = MakeShareable((FNavDataGenerator*)Generator);
			Generator->Init();
		}

		UNavigationSystemV1* NavSys = FNavigationSystem::GetCurrent<UNavigationSystemV1>(World);
		if (NavSys)
		{
			RestrictBuildingToActiveTiles(IsUsingActiveTilesGeneration(*NavSys));
		}
	}
}

