// Validates Sprites.json / Spells.json: JSON parses, rows equal length, every non-transparent char is in the palette,
// palette keys have no case clash. Prints the tile sprites as text.
const fs = require('fs');
const dir = 'C:/GameJam/Glyphbound/Content/Data/';
const sprites = JSON.parse(fs.readFileSync(dir + 'Sprites.json', 'utf8')).Sprites;
JSON.parse(fs.readFileSync(dir + 'Spells.json', 'utf8'));
let bad = 0;
for (const s of sprites) {
  const keys = Object.keys(s.Palette);
  const lower = keys.map(k => k.toLowerCase());
  if (new Set(lower).size !== lower.length) { console.log('CASE CLASH', s.Id); bad++; }
  const w = s.Rows[0].length;
  s.Rows.forEach((r, i) => {
    if (r.length !== w) { console.log('RAGGED', s.Id, i, r.length, JSON.stringify(r)); bad++; }
    for (const c of r) {
      if (c !== '.' && c !== ' ' && !keys.includes(c)) { console.log('NO COLOR', s.Id, i, c); bad++; }
    }
  });
  if (s.Id.startsWith('tile_')) {
    console.log(s.Id, w + 'x' + s.Rows.length);
  }
}
const ids = sprites.map(s => s.Id);
if (new Set(ids).size !== ids.length) { console.log('DUPLICATE IDS'); bad++; }
console.log(bad ? 'BAD ' + bad : 'OK');

